import { expect, test } from "./fixture";

/**
 * Signing in, and the frame of the dashboard once you are.
 *
 * The sign-in is the part worth a browser. A magic link generated by the admin
 * API comes back in the implicit flow, which means the session arrives in a URL
 * fragment: `/auth/callback` finds no code, bounces to `/auth/hash`, the
 * browser reads the fragment and establishes the session, and `/auth/land`
 * decides where the founder belongs. Three of those four steps only exist
 * because a fragment never reaches a server, and no test outside this file
 * has ever run them.
 */

test("the dashboard is closed to a visitor with no session", async ({ page }) => {
  await page.goto("/");
  await expect(page).toHaveURL(/\/signup\?next=%2F$/);
  await expect(page.getByRole("heading", { name: "Create your Euclid account" })).toBeVisible();
});

test("a magic link signs the founder in and lands them on their board", async ({
  page,
  board,
  founder,
}) => {
  await founder.signIn(page);

  // The greeting is time-of-day dependent; the name is not.
  await expect(page.getByRole("heading", { level: 1 })).toContainText("Maya");
  await expect(page.getByText("Here is what Driftnote users asked for this week.")).toBeVisible();
  await expect(page).toHaveURL(/\/$/);

  // The dashboard's link out to the public board is the board the fixture
  // made, which is the cheapest proof that the session resolved to the right
  // workspace rather than any workspace.
  await expect(page.getByRole("link", { name: /View public board/ })).toHaveAttribute(
    "href",
    `/b/${board.publicId}`,
  );
});

test("the sidebar reaches the feedback inbox and the install snippet", async ({
  page,
  board,
  founder,
}) => {
  await founder.signIn(page);

  await page.getByRole("link", { name: /^Feedback/ }).click();
  await expect(page).toHaveURL(/\/feedback/);
  for (const post of board.posts) {
    await expect(page.getByText(post.title, { exact: true }).first()).toBeVisible();
  }

  await page.getByRole("link", { name: "Install widget" }).click();
  await expect(page).toHaveURL(/\/install/);
  // The snippet a founder copies has to carry their own board id. Getting this
  // wrong is invisible until someone installs the widget and sees nothing.
  await expect(page.getByText(`data-board="${board.publicId}"`).first()).toBeVisible();
});

test("signing out closes the dashboard again", async ({ page, founder }) => {
  await founder.signIn(page);
  await expect(page.getByRole("heading", { level: 1 })).toContainText("Maya");

  // Posted rather than clicked, because nothing in the dashboard links to
  // `/auth/signout` yet — the route is POST-only and has no button. The
  // request goes through the page's own context, so it carries and then clears
  // the same session cookies the browser holds.
  const signedOut = await page.request.post("/auth/signout");
  expect(signedOut.url()).toMatch(/\/signup$/);

  await page.goto("/");
  await expect(page).toHaveURL(/\/signup\?next=%2F$/);
});
